import unittest
from candidate import strlen

class TestStringLength(unittest.TestCase):
    def test_normal_string_length(self):
        self.assertEqual(strlen("hello"), 5)

    def test_empty_string(self):
        self.assertEqual(strlen(""), 0)

    def test_single_character(self):
        self.assertEqual(strlen("a"), 1)

    def test_long_string(self):
        self.assertEqual(strlen("a" * 1000), 1000)

    def test_unicode_characters(self):
        self.assertEqual(strlen("café"), 5)

    def test_boundary_condition_minus_one(self):
        self.assertEqual(strlen("a" * (-1)), 0)

    def test_none_input(self):
        with self.assertRaises(TypeError):
            strlen(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            strlen(123)

    def test_string_with_spaces(self):
        self.assertEqual(strlen("a b c"), 5)

    def test_string_with_special_chars(self):
        self.assertEqual(strlen("!@#$%^&*()"), 10)

    def test_string_with_newlines(self):
        self.assertEqual(strlen("line1\nline2"), 8)
